grupos.css:
*{box-sizing:border-box}
body{min-width:320px;min-height:100dvh;margin:0;background:var(--page);color:var(--text);font-family:"Plus Jakarta Sans","Segoe UI",Arial,sans-serif}
button,input{font:inherit}
button{cursor:pointer}
a{color:inherit;text-decoration:none}
.prototype-screen{min-height:100dvh}
.screen-slot--main{display:block;width:min(100%,720px);margin:0 auto;padding:22px 16px 28px}
.screen-slot--main>*+*{margin-top:12px}
.screen-layout{min-height:100dvh;}
.home-profissional{min-height:100dvh;}
.screen-slot--main{display:block;width:min(100%,720px);margin:0 auto;padding:22px 16px 28px;}
